  aiLabelRow.style.cssText = "display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;";
  aiLabelRow.innerHTML =
    '<div style="font-size:9px; font-weight:700; color:#fff; background:#546e7a; padding:2px 8px; text-transform:uppercase; letter-spacing:0.5px;">✨ AI Draft</div>';
  var regenLink = document.createElement("div");
  regenLink.style.cssText = "font-size:10px; color:#1565c0; cursor:pointer; font-weight:600;";
  regenLink.textContent = "🔄 Regenerate";
  regenLink.onmouseover = function () {
    regenLink.style.textDecoration = "underline";
  };
  regenLink.onmouseout = function () {
    regenLink.style.textDecoration = "none";
  };
  aiLabelRow.appendChild(regenLink);
  aiCard.appendChild(aiLabelRow);
  var formatNote = document.createElement("div");
  formatNote.style.cssText = "font-size:9px; color:#aaa; margin-bottom:8px; display:flex; align-items:center; gap:4px;";
  formatNote.innerHTML = "💡 Output formatted for <strong>Gmail</strong>: Arial, 13.3px, line-height 1.38";
  aiCard.appendChild(formatNote);
  var aiOutput = document.createElement("div");
  aiOutput.style.cssText = "font-family:Arial,Helvetica,sans-serif; font-size:13.3px; color:#222222; line-height:1.5; padding:10px 12px; background:#fff; border:1px solid #e0e0e0; border-left:4px solid #546e7a; max-height:250px; overflow-y:auto; white-space:normal;";
  aiCard.appendChild(aiOutput);
  // out.appendChild(aiCard); // hidden — source box shows the diff instead
  // Post-generation buttons (Copy / Insert / Redline) live inside actionRow
  // alongside Generate. Hidden until first AI generation completes.
  function _ehMakeBtn(label, bgGradient, color) {
    var b = document.createElement("button");
    b.className = "btn-action";
    b.style.cssText = "padding:6px 10px; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; cursor:pointer; transition:all 0.2s; display:none; align-items:center; justify-content:center; gap:4px; line-height:1.2;" +
      (bgGradient ? "border:none; background:" + bgGradient + "; color:" + (color || "#fff") + "; box-shadow:0 2px 6px rgba(0,0,0,0.15);"
                  : "border:1px solid #b0bec5; background:#fff; color:#546e7a;");
    b.innerHTML = label;
    return b;
  }
  var copyBtn = _ehMakeBtn("📋 Copy");
  copyBtn.onclick = function () {
    var range = document.createRange();
    range.selectNodeContents(aiOutput);
    var sel = window.getSelection();
    sel.removeAllRanges(); sel.addRange(range);
    document.execCommand("copy");
    sel.removeAllRanges();
    copyBtn.innerHTML = "✅ Copied!";
    setTimeout(function () { copyBtn.innerHTML = "📋 Copy"; }, 2000);
  };
  var insertBtn = _ehMakeBtn("✏️ Insert", "linear-gradient(180deg,#1976d2,#0d47a1)");
  insertBtn.onclick = function () {
    if (!aiOutput.innerHTML || !aiOutput.innerHTML.trim()) {
      showToast("⚠️ Generate a draft first.", "warning"); return;
    }
    var html = '<div style="font-family:Arial,Helvetica,sans-serif; font-size:13.3px; color:#222222; line-height:1.38;">' + aiOutput.innerHTML + "</div>";
    // Insert WITHOUT track-changes — Email Helper output should land as clean
    // text. Save the doc's current tracking mode, force it off, insert at the
    // cursor, then restore the original mode.
    Word.run(async function (context) {
      var doc = context.document;
      doc.load("changeTrackingMode");
      await context.sync();
      var prevMode = doc.changeTrackingMode;
      try { doc.changeTrackingMode = "Off"; } catch (_) {}
      await context.sync();
      var inserted = false;
      try {
        var sel = doc.getSelection();
        sel.insertHtml(html, "Replace");
        await context.sync();
        inserted = true;
      } catch (selErr) {
        // Fallback: append at body end if selection insert wasn't valid.
        try {
          doc.body.insertHtml(html, "End");
          await context.sync();
          inserted = true;
        } catch (_) { /* both failed — handled below */ }
      }
      // Always try to restore original tracking mode, even if insert failed.
      try { doc.changeTrackingMode = prevMode; } catch (_) {}
      await context.sync();
      return inserted;
    }).then(function (ok) {
      if (ok) {
        insertBtn.innerHTML = "✅ Inserted!";
        showToast("✅ Email draft inserted at cursor (no redlines).");
        setTimeout(function () { insertBtn.innerHTML = "✏️ Insert"; }, 2000);
      } else {
        showToast("❌ Insert failed.", "error");
      }
    }).catch(function (e) {
      showToast("❌ Insert failed: " + (e && e.message ? e.message : "unknown"), "error");
    });
  };
  // Apply as Redline — bookmark-anchored. Replaces the captured range with
  // AI text under track-changes. Word shows redline natively (no JS hunking).
  var redlineBtn = _ehMakeBtn("🖊️ Redline", "linear-gradient(180deg,#7b1fa2,#4a148c)");
  redlineBtn.onclick = function () {
    if (!lastAiText) { showToast("⚠️ No generated text yet.", "warning"); return; }
    if (!captureBookmark) {
      showToast("⚠️ No anchor — re-capture from a Word selection so Redline knows where to apply.", "warning");
      return;
    }
    if (typeof computeWordDiff !== "function") { showToast("❌ Diff helper unavailable.", "error"); return; }
    redlineBtn.innerHTML = "⏳...";
    redlineBtn.disabled = true;
    var isAggressive = aggressiveness === "aggressive";
    Word.run(async function (context) {
      var bRange = context.document.getBookmarkRangeOrNullObject(captureBookmark);
      bRange.load("isNullObject, text");
      await context.sync();
      if (bRange.isNullObject) throw new Error("Bookmark missing — was the original selection deleted?");
      // Aggressive intensity = wholesale replace (Word tracks the entire diff).
      // Other intensities = surgical hunk-by-hunk for cleaner per-change marks.
      if (isAggressive) {
        if (typeof safeToggleTracking === "function") await safeToggleTracking(context, true);
        bRange.insertText(lastAiText, "Replace");
        await context.sync();
        return { applied: 1, skipped: 0, totalChanges: 1 };
      }
      var sourceText = bRange.text || capturedText;
      var hunks = computeWordDiff(sourceText, lastAiText) || [];
      if (typeof safeToggleTracking === "function") await safeToggleTracking(context, true);
      var applied = 0, skipped = 0;
      for (var i = 0; i < hunks.length; i++) {
        var h = hunks[i];
        if (h.type === "equal") continue;
        var prev = "", next = "";
        if (i > 0 && hunks[i - 1].type === "equal") {
          var pw = hunks[i - 1].text.trim().split(/\s+/);
          if (pw.length > 0) prev = pw.slice(-2).join(" ") + " ";
        }
        if (i < hunks.length - 1 && hunks[i + 1].type === "equal") {
          var nw = hunks[i + 1].text.trim().split(/\s+/);
          if (nw.length > 0) next = " " + nw.slice(0, 2).join(" ");
        }
        var oldT = h.oldWords ? h.oldWords.join(" ") : "";
        var newT = h.newWords ? h.newWords.join(" ") : "";
        var pOld = (prev + oldT + next).trim();
        var pNew = (prev + newT + next).trim();
        if (!pOld) pOld = oldT;
        var sr = bRange.search(pOld, { matchCase: false, matchWholeWord: false, ignoreSpace: true, ignorePunctuation: true });
        sr.load("items");
        await context.sync();
        if (sr.items.length > 0) {
          sr.items[0].insertText(pNew, "Replace");
          await context.sync();
          applied++;
        } else { skipped++; }
      }
      return { applied: applied, skipped: skipped, totalChanges: hunks.filter(function (h) { return h.type !== "equal"; }).length };
    }).then(function (res) {
      redlineBtn.disabled = false;
      var msg = "✅ " + res.applied + "/" + res.totalChanges + " applied" + (res.skipped ? " (" + res.skipped + " skipped)" : "");
      redlineBtn.innerHTML = msg;
      showToast(msg + " — review in Word's track-changes UI.", res.applied ? "success" : "warning");
      setTimeout(function () { redlineBtn.innerHTML = "🖊️ Redline"; }, 3000);
    }).catch(function (e) {
      redlineBtn.disabled = false;
      redlineBtn.innerHTML = "❌";
      showToast("❌ Redline failed: " + (e && e.message ? e.message : "unknown"), "error");
      setTimeout(function () { redlineBtn.innerHTML = "🖊️ Redline"; }, 3000);
    });
  };
  actionRow.appendChild(copyBtn);
  actionRow.appendChild(insertBtn);
  actionRow.appendChild(redlineBtn);
  var homeLink = document.createElement("div");
  homeLink.style.cssText = "display:block; text-align:center; padding:10px; font-size:11px; color:#78909c; cursor:pointer; font-weight:600; transition:color 0.2s; font-family:'Book Antiqua','Palatino Linotype',serif; text-transform:uppercase; letter-spacing:0.8px;";
  homeLink.textContent = "🏠 Return Home";
  homeLink.onmouseover = function () {
    homeLink.style.color = "#1565c0";
  };
  homeLink.onmouseout = function () {
    homeLink.style.color = "#78909c";
  };
  homeLink.onclick = function () {
    showHome();
  };
  out.appendChild(homeLink);
  function runGeneration() {
    if (!capturedText.trim() && !instrTextarea.value.trim()) {
      showToast("⚠️ Please capture text or enter instructions first.");
      return;
    }
    // If the user trained Humanize on their own writing samples, use them as a
    // style reference. Otherwise fall back to generic humanization. Reads from the
    // in-memory cache populated by _ehLoadHumanizeTraining (IndexedDB on mount).
    var humanizeTrainingText = (_ehHumanizeTraining || "").trim();
    var humanizePrompt = humanizeTrainingText
      ? ("Rewrite this to sound like the SPECIFIC HUMAN AUTHOR whose writing samples are provided below. " +
         "Match their sentence length, vocabulary, formality, rhythm, transitions, and any quirks. Do NOT use AI-flavored phrases " +
         "(\"furthermore,\" \"in conclusion,\" \"it is important to note\") unless the samples themselves use them. " +
         "Preserve the original meaning, just speak in their voice.\n\n" +
         "AUTHOR'S WRITING SAMPLES (study these carefully — emulate their voice):\n\"\"\"\n" +
         humanizeTrainingText +
         "\n\"\"\"")
      : "Rewrite this to sound natural and human-written, not robotic or AI-generated. Use conversational professional language.";
    var toneMap = {
      polish: "Polish this text — tighten phrasing, fix awkward constructions, improve flow, remove filler. Keep the original meaning intact; just make it read better.",
      humanize: humanizePrompt,
      formalize: "Formalize this text — elevate the register to formal business / legal correspondence. Replace casual phrasing with precise, professional language. Avoid contractions and colloquialisms.",
      assertive: "Rewrite this in a firm, assertive, and confident professional tone.",
    };
    var aggrMap = {
      minimal:    "INTENSITY: Apply the LIGHTEST possible touch — only adjust what is strictly necessary to satisfy the tone(s). Preserve as much of the original wording as possible.",
      balanced:   "INTENSITY: Apply moderate, balanced changes to satisfy the tone(s) without overhauling the text.",
      aggressive: "INTENSITY: Apply BOLD, extensive rewrites — fully transform the text to embody the tone(s). Restructure freely.",
    };
    var lenMap = {
      shorter: "LENGTH: Shorten the result noticeably — keep only the essentials. Aim for ~60% of the source length.",
      same:    "LENGTH: Match the source length closely — do not lengthen or shorten substantially.",
      longer:  "LENGTH: Expand the result with more detail, context, and professional depth. Aim for ~150% of the source length.",
    };
    var toneInstruction;
    var customText = customInput.value.trim();
    if (customText) {
      toneInstruction = customText;
    } else {
      var picked = (selectedTones.length ? selectedTones : ["humanize"]);
      toneInstruction = picked.map(function (id) { return toneMap[id]; }).filter(Boolean).join(" AND ");
    }
    toneInstruction = toneInstruction
      + "\n" + (aggrMap[aggressiveness] || aggrMap.balanced)
      + "\n" + (lenMap[lengthChoice] || lenMap.same);
    var contextDocs = "";
    if (uploadedFiles.length > 0) {
      contextDocs = "\n\nThe user has attached " + uploadedFiles.length + " reference document(s): ";
      uploadedFiles.forEach(function (f) {
        contextDocs += f.name + ", ";
        if (f.content && typeof f.content === "string" && !f.content.startsWith("data:")) {
          contextDocs += "\nContent from " + f.name + ":\n" + f.content.substring(0, 5000) + "\n";
        }
      });
    }
    var docInstructions = instrTextarea.value.trim();
    var docInstrBlock = docInstructions ? "\n\nDocument Analysis Instructions: " + docInstructions : "";
    var prompt = `You are a professional legal email drafting assistant. Generate a polished email based on the following.
FORMATTING RULES:
- Output ONLY the email body as plain HTML using <br> for line breaks.
- Do NOT include Subject line, To/From headers, or any markdown.
- Use the default Gmail font: Arial, 13.3px, color #222222, line-height 1.38.
- Use <b> for bold and <i> for italic (not <strong> or <em>).
- Separate paragraphs with <br><br>.
- The email should look exactly as it would appear in Gmail's compose window.
TONE: ${toneInstruction}
SOURCE TEXT (from the user's document):
"""
${capturedText || "(No text selected — generate based on the instructions below)"}
"""
${contextDocs}${docInstrBlock}
Generate the email now. Output ONLY the HTML email body, nothing else.`;
    genBtn.innerHTML =
      '<div style="width:14px;height:14px;border:2px solid rgba(255,255,255,0.3);border-top-color:#fff;border-radius:50%;animation:spin 0.6s linear infinite;display:inline-block;"></div> Generating...';
    genBtn.style.pointerEvents = "none";
    genBtn.style.opacity = "0.7";
    aiCard.style.display = "none";
    copyBtn.style.display = "none";
    insertBtn.style.display = "none";
    redlineBtn.style.display = "none";
    callGemini(API_KEY, prompt)
      .then(function (result) {
        if (!result) {
          showToast("❌ No response from AI.");
          return;
        }
        var clean = result
          .replace(/```html/gi, "")
          .replace(/```/g, "")
          .trim();
        // Render formatted preview AND keep a plain-text version for diff/redline.
        // white-space:normal lets <br> tags render as line breaks; otherwise the
        // pre-wrap CSS would double up newlines.
        aiOutput.innerHTML =
          '<div style="font-family:Arial,Helvetica,sans-serif; font-size:13.3px; color:#222222; line-height:1.5; white-space:normal;">' +
          clean +
          "</div>";
        // Capture plain-text version (innerText respects <br> as \n).
        lastAiText = (aiOutput.innerText || "").replace(/\r\n?/g, "\n").trim();
        // Build per-hunk diff (capturedText vs AI text) so the preview shows
        // surgical per-change marks, and so each hunk is individually
        // accept/reject/edit-able. Reset decisions on every generate.
        _ehDecisions = {};
        _ehHunks = (capturedText.trim() && typeof computeWordDiff === "function")
          ? computeWordDiff(_ehCleanText(capturedText), _ehCleanText(lastAiText))
          : [];
        if (_ehHunks.length) _ehRenderHunkedRedline();
        // Reveal the post-gen actions inside actionRow (alongside Generate).
        copyBtn.style.display = "inline-flex";
        insertBtn.style.display = "inline-flex";
        redlineBtn.style.display = "inline-flex";
      })
      .catch(function (err) {
        showToast("❌ AI Error: " + err.message);
      })
      .finally(function () {
        genBtn.innerHTML = "🚀 Generate";
        genBtn.style.pointerEvents = "";
        genBtn.style.opacity = "";
      });
  }
  genBtn.onclick = runGeneration;
  regenLink.onclick = runGeneration;
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var showEmailComposerApp = window.showEmailComposerApp;
  if (!showEmailComposerApp) {
    eli.log.event("tool", "email_helper_load_failed", {});
    return;
  }

  // ─── Tile handler ────────────────────────────────────────────────
  function _open() {
    if (!eli.ai || typeof eli.ai.hasApiKey !== "function" || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && typeof eli.settings.show === "function") eli.settings.show();
      return;
    }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedEmailHelper"); } catch (e) {}
    try { showEmailComposerApp(); }
    catch (e) {
      eli.log.event("tool", "email_helper_launch_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Email Helper failed to open: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_email_helper: _open },
    email_helper: { open: _open },
    activity_restore: { "email-helper": function () { _open(); } },
  });

  // ─── v2 globals → v3 provider bridges ────────────────────────────

  // `callGemini` / `callGeminiStream` / `API_KEY` shims now live in the
  // kernel (taskpane_v3.js — single source of truth, no race conditions
  // between tools). This tool's v2 files reach for them directly via
  // `window.callGemini(API_KEY, prompt)` and the kernel routes through
  // `eli.ai.complete`.

  // v2 `loadFeatureData(storeName)` — sometimes used by email_helper for
  // saved templates. Same bridge pattern as compare.
  if (typeof window.loadFeatureData !== "function") {
    window.loadFeatureData = function (storeName) {
      if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
      return eli.storage.getAll(storeName).then(function (rows) {
        return (rows || []).filter(function (r) {
          return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
        });
      }).catch(function () { return []; });
    };
  }

  // v2 `recordEliStat(key, count?)` — usage tracking. Bridge to v3 stats.
  if (typeof window.recordEliStat !== "function") {
    window.recordEliStat = function (statKey, count) {
      try { if (eli.stats && eli.stats.record) eli.stats.record(statKey, count); } catch (e) {}
    };
  }

  // v2 `setLoading(on, mode?)` — kernel may already expose this; if not,
  // shim with a no-op (toasts cover the UX).
  if (typeof window.setLoading !== "function") {
    window.setLoading = function () { /* no-op — kernel covers loading via FSM */ };
  }
  if (typeof window.handleError !== "function") {
    window.handleError = function (err) {
      eli.log.event("tool", "email_helper_runtime_error", { msg: err && err.message });
      if (typeof showToast === "function") showToast("Error: " + (err && err.message || "unknown"), "err");
    };
  }

  // ─── Activity entry on launch ────────────────────────────────────
  if (eli.activity && typeof eli.activity.add === "function") {
    var prevOpen = _open;
    _open = function () {
      try {
        eli.activity.add({
          type: "email-helper",
          icon: "✉️",
          label: "Email Helper",
          summary: "Opened email composer",
          payload: { ts: Date.now() },
          restoreChannel: "activity_restore",
          restoreKey: "email-helper",
        });
      } catch (e) {}
      return prevOpen();
    };
  }

  eli.log.event("tool", "email_helper_initialized", {});
}
